import os
import sys

import jd2chm_log
import jd2chm_conf

logging = None
config = None

def getAppDir():
  if hasattr(sys, "frozen"): # py2exe
    return os.path.dirname(sys.executable)
  return os.path.dirname(sys.argv[0])

def getLogging(level=2):
  global logging
  if not logging:
    logging = jd2chm_log.Jd2chmLogging(level)
  return logging

def getLog():
  """Faciliate sharing the logger accross the different modules."""
  return getLogging().logger

def getConf():
  global config
  if not config:
    config = jd2chm_conf.Jd2chmConfig()
    config.init()
  return config

def prettyPrintExecutionTime(seconds):
  seconds = int(seconds)
  units = [("d", 86400), ("h", 3600), ("min", 60), ("s", 1)]
  res = []
  for unit in units:
    quotient = seconds // unit[1]
    if quotient:
      res.append("%d%s" % (quotient, unit[0]))
      seconds = seconds % unit[1]
      if not seconds:
        break
  if not res:
    return "<1s"
  return " ".join(res)

def prettyPrintSize(size,_IE_=False):
  units = [("KB", 1024), ("MB", 1024), ("GB", 1024), ("TB", 1024)]
  original = ceil(size)
  for unit in units:
    if size < unit[1]:
      break
    size = size / unit[1]
  res = "%s%s" % (round(size, 2), unit[0])
  if _IE_:
    res = "%s %s" % (original, res)
  return res

