# -*- coding: utf-8 -*-
"""flake8 plugin to check pep257 docstrings convention needs error code and class parser for be
included as module into flake8
"""
import io

import pep8
import pep257

__version__ = '0.2.1.post1'


class pep257Checker(object):
    """flake8 needs a class to check python file."""

    name = 'flake8-docstrings'
    version = __version__

    STDIN_PREFIX = 'stdin:'

    def __init__(self, tree, filename='(none)', builtins=None):
        self.tree = tree
        self.filename = filename
        self.source = self.load_source()

    def run(self):
        """Use directly check() api from pep257."""
        for error in pep257.check_file(io.StringIO(self.source),
                                      [self.filename]):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))

    def load_source(self):
        """Load source from file or stdin."""
        if self.filename.startswith(self.STDIN_PREFIX):
            return pep8.stdin_get_value()
        with open(self.filename, 'rU') as f:
            return f.read()

# -*- coding: utf-8 -*-
"""pep257 docsstrings convention needs error code and class parser for be
included as module into flake8
"""
import io

import pep8
import pep257

__version__ = '0.2.1.post1'


class pep257Checker(object):
    """flake8 needs a class to check python file."""

    name = 'flake8-docstrings'
    version = __version__ + ', pep257: {0}'.format(pep257.__version__)

    STDIN = '-'

    def __init__(self, tree, filename='(none)', builtins=None):
        """Keep parsed tree for later use in check method."""
        self.tree = tree
        self.filename = filename
        self.source = self.load_source()

    def run(self):
        """Use directly check() api from pep8 and pep257."""
        for error in pep257.check([self.filename], self.source):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))

    def load_source(self):
        """Load source code from stdin or from the file."""
        if self.filename == self.STDIN:
            return pep8.stdin_get_value()
        with io.open(encoding='utf-8') as fd:
            return fd.read()

# -*- coding: utf-8 -*-
"""flake8 plugin to check pep257 docstrings convention needs error code and class parser for be
included as module into flake8
"""
import pep8
import pep257

__version__ = '0.2.1.post1'


class pep257Checker(object):

    """flake8 needs a class to check python file."""

    name = 'flake8-docstrings'
    version = __version__

    def __init__(self, tree, filename='(none)', builtins=None):
        self.tree = tree
        self.filename = filename or '(none)'
        self.source = self._read_source()

    def run(self):
        """Use directly check() api from pep257."""
        for error in pep257.check_source(self.source, self.filename):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))

    @staticmethod
    def _read_source():
        """Read source from stdin."""
        return pep8.stdin_get_value()
